export const duration=32;
export const config={title:'銀燒結固晶',sceneLabel:'乾式置晶的壓力輔助銀燒結，主接合層與顆粒放大區同步',question:'銀保持固態，顆粒逐步連成接合層',overview:28,notes:['採InFORCE MF壓力輔助乾式置晶代表順序：模板印刷、預乾燥、加熱貼放，再壓力燒結。資料表第1頁流程圖確認置晶時基板與晶粒需加熱；本圖省略製程數值，不是可直接使用的溫壓配方。','以鍍銀銅墊及具有相容銀表面金屬化的功率晶粒為例。下方陶瓷提供電氣絕緣，導電虛線只走金屬層，不穿越陶瓷。基板全程有下承托，上壓頭經晶粒傳遞壓力。','濕膏含銀顆粒與有機載體。預乾燥去除大部分揮發成分，後續加熱移除剩餘有機物；淡褐色離開線索僅表示去向，不指定全部成分的化學反應。灰色銀顆粒從未畫成液滴。','A為同一接合層的概念放大圖，粒數與孔隙不按比例。接觸處成頸、頸部擴大，層厚縮小但保留孔隙；連結不是瞬間變成無孔實心銀板。熱與電路徑為定性示意，不代表量測效率。'],sources:[['Indium：InFORCE乾式置晶銀膏','https://www.indium.com/products/sintering-materials/pressure-sintering/inforce/'],['InFORCE MF產品資料表：流程圖與相容表面','https://www.indium.com/wp-content/uploads/2025/03/InFORCE%C2%AEMF-Pressure-Assisted-Ag-Sinter-Paste-for-Die-Attach-PDS-100320-R1.pdf'],['Indium：低孔隙銀燒結接合的顆粒成頸說明','https://imapsource.org/article/67725-silver-sintering-paste-rendering-low-porosity-joint-for-high-power-die-attach-application.pdf']]};
export const steps=[{end:6,title:'印刷濕銀膏',key:5,what:'在已準備的鍍銀墊上印刷銀膏，灰色顆粒分散於褐色載體。',detail:'此時不是已完成的實心金屬板；A區放大同一接合層。'},{end:11,title:'預乾燥',key:10,what:'預乾燥去除多數揮發成分，接合層變薄。',detail:'仍需後續加熱與壓力，不能把乾燥當成完成燒結。'},{end:16,title:'加熱貼放晶粒',key:15,what:'加熱後，金屬化晶粒背面貼到預乾燥層。',detail:'上下相容金屬表面相向，基板下方有支撐。'},{end:24,title:'加壓與顆粒成頸',key:21,what:'施加熱與壓力，顆粒接觸處逐步連結，孔隙縮小。',detail:'銀保持固態，主層與放大區同時變薄；孔隙不歸零。'},{end:27,title:'冷卻與卸載',key:26,what:'完成燒結後冷卻，壓頭釋放並退出。',detail:'燒結層留在晶粒底下，不回復成濕膏。'},{end:32,title:'金屬路徑與移交',key:28,what:'熱與電可經金屬化背面、燒結銀層到鍍銀銅墊。',detail:'陶瓷不在電路徑中；成品離開後，新晶粒與基板進場。'}];
export const ramp=(t,a,b)=>Math.max(0,Math.min(1,(t-a)/(b-a)));export const ease=x=>x*x*(3-2*x);
export function stateAt(t){t=Math.max(0,Math.min(duration-.0001,t));const index=steps.findIndex(s=>t<s.end),dry=ramp(t,6,10),neck=ramp(t,17,23);return {t,index,step:steps[index],entry:ease(ramp(t,0,1)),print:ramp(t,1,4),dry,neck,organic:(1-.85*dry)*(1-neck),thickness:26-7*dry-7*neck,place:ease(ramp(t,11,14.5)),pressure:ease(ramp(t,16,17))*(1-ease(ramp(t,24.5,26.5))),hot:t>=6&&t<24.5,connected:t>=27,exit:ease(ramp(t,30,31.7))};}
